1	package netdiag
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"net/netip"
8		"testing"
9		"time"
10	
11		tea "charm.land/bubbletea/v2"
12	
13		"github.com/anthnel/devdesk/internal/netcheck"
14		"github.com/anthnel/devdesk/internal/nettrace"
15	)
16	
17	const producerWait = 2 * time.Second
18	
19	// fakeEngine records its calls; no socket, no resolver.
20	type fakeEngine struct {
21		resolveCalls int
22		resolveHost  string
23		resolveCtx   context.Context
24		traceCalls   int
25		traceAddr    netip.Addr
26		traceOpts    nettrace.Options
27		traceCtxErr  error
28		routeCalls   int
29		routeAddr    netip.Addr
30	
31		routeFn   func(ctx context.Context, a netip.Addr) (netcheck.RouteHop, error)
32		resolveFn func(ctx context.Context, host string) ([]netip.Addr, error)
33		traceFn   func(ctx context.Context, a netip.Addr, o nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error)
34	}
35	
36	func (f *fakeEngine) engine() pathEngine {
37		return pathEngine{
38			supported: func() error { return nil },
39			resolve: func(ctx context.Context, host string) ([]netip.Addr, error) {
40				f.resolveCalls++
41				f.resolveHost = host
42				f.resolveCtx = ctx
43				if f.resolveFn == nil {
44					return nil, errors.New("unexpected resolve")
45				}
46				return f.resolveFn(ctx, host)
47			},
48			route: func(ctx context.Context, a netip.Addr) (netcheck.RouteHop, error) {
49				f.routeCalls++
50				f.routeAddr = a
51				if f.routeFn == nil {
52					return defaultRouteHop(), nil
53				}
54				return f.routeFn(ctx, a)
55			},
56			trace: func(ctx context.Context, a netip.Addr, o nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error) {
57				f.traceCalls++
58				f.traceAddr = a
59				f.traceOpts = o
60				f.traceCtxErr = ctx.Err()
61				if f.traceFn == nil {
62					return nettrace.Result{Target: a}, nil
63				}
64				return f.traceFn(ctx, a, o, onHop)
65			},
66		}
67	}
68	
69	func hopAt(ttl int) nettrace.Hop {
70		return nettrace.Hop{TTL: ttl, Kind: nettrace.HopRouter, Addr: netip.MustParseAddr("10.0.0.1")}
71	}
72	
73	// runProducer calls producePath synchronously with nobody reading the
74	// channel, failing if it does not return (the channel capacity must hold).
75	func runProducer(t *testing.T, ctx context.Context, gen int, tg pathTarget, rt time.Duration, e pathEngine) []tea.Msg {
76		t.Helper()
77		out := make(chan tea.Msg, pathChanCap)
78		done := make(chan struct{})
79		go func() {
80			defer close(done)
81			producePath(ctx, gen, tg, rt, e, out)
82		}()
83		select {
84		case <-done:
85		case <-time.After(producerWait):
86			t.Fatal("producePath did not return: the producer blocked")
87		}
88		var msgs []tea.Msg
89		for {
90			select {
91			case m, ok := <-out:
92				if !ok {
93					return msgs
94				}
95				msgs = append(msgs, m)
96			default:
97				t.Fatal("channel not closed after producePath returned")
98				return nil
99			}
100		}
101	}
102	
103	func TestPathChanCapHoldsAWholeTrace(t *testing.T) {
104		if want := nettrace.MaxHopsLimit + 2; pathChanCap != want {
105			t.Fatalf("pathChanCap = %d, want %d", pathChanCap, want)
106		}
107		if pathChanCap != 32 {
108			t.Fatalf("pathChanCap = %d, want 32", pathChanCap)
109		}
110	}
111	
112	func TestProducePathLiteralIPv4SkipsResolve(t *testing.T) {
113		f := &fakeEngine{traceFn: func(_ context.Context, a netip.Addr, _ nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error) {
114			onHop(hopAt(1))
115			onHop(hopAt(2))
116			return nettrace.Result{Target: a, Outcome: nettrace.OutcomeReached, Hops: []nettrace.Hop{hopAt(1), hopAt(2)}}, nil
117		}}
118		msgs := runProducer(t, context.Background(), 7, pathTarget{Host: "1.1.1.1"}, time.Second, f.engine())
119	
120		if f.resolveCalls != 0 {
121			t.Fatalf("resolve called %d times for a literal IPv4", f.resolveCalls)
122		}
123		if f.traceOpts != (nettrace.Options{}) {
124			t.Fatalf("trace options = %+v, want the zero Options", f.traceOpts)
125		}
126		if len(msgs) != 4 {
127			t.Fatalf("got %d messages, want 4 (resolved, 2 hops, done): %#v", len(msgs), msgs)
128		}
129		res, ok := msgs[0].(pathResolvedMsg)
130		if !ok || res.addr != netip.MustParseAddr("1.1.1.1") || res.gen != 7 {
131			t.Fatalf("msgs[0] = %#v, want pathResolvedMsg{7, 1.1.1.1}", msgs[0])
132		}
133		for i, ttl := range []int{1, 2} {
134			h, ok := msgs[1+i].(pathHopMsg)
135			if !ok || h.hop.TTL != ttl || h.gen != 7 {
136				t.Fatalf("msgs[%d] = %#v, want pathHopMsg ttl %d gen 7", 1+i, msgs[1+i], ttl)
137			}
138		}
139		d, ok := msgs[3].(pathDoneMsg)
140		if !ok || d.err != nil || d.gen != 7 || d.result.Outcome != nettrace.OutcomeReached || len(d.result.Hops) != 2 {
141			t.Fatalf("msgs[3] = %#v, want a clean pathDoneMsg", msgs[3])
142		}
143	}
